  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Bicuculline, a phthalideisoquinoline alkaloid sharing the same core connectivity as the query, penetrated the rat brain in a dose-dependent manner after systemic administration, directly supporting CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Isocorydine, an N-methylated aporphine alkaloid with similar methoxy-substituted aromatic rings, was detected in rat brain within 10 minutes of administration, demonstrating rapid BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Stepholidine, a related tetrahydroprotoberberine alkaloid, showed good brain penetration with a brain:plasma AUC ratio of about 0.7 in rats, supporting meaningful CNS exposure for this alkaloid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tetrahydroberberine was detected in rat CSF after systemic administration, confirming passage across the BBB for a close congener.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Apomorphine, a basic N-methylated aporphine, readily crossed the BBB in rats with brain concentrations exceeding plasma levels, supporting CNS access for this alkaloid family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a noscapine-like phthalideisoquinoline alkaloid. Multiple high-transfer analogues—especially bicuculline, isocorydine, stepholidine, tetrahydroberberine, and apomorphine—provide direct experimental evidence of brain or CSF penetration after systemic administration. The physicochemical prior is also favorable. The few poor-penetration records have very low transfer scores and belong to structurally distant or permanently charged chemotypes, so they do not override the strong positive evidence.",
  "evidence_gaps": [
    "No direct noscapine-specific brain or CSF pharmacokinetic measurement is included in the provided records; the decision relies on high-transfer close analogues.",
    "No explicit P-gp or other efflux transporter data are available for the query, but net brain penetration in multiple related alkaloids suggests efflux is not prohibitive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

